   kidx = SEED % klen;
   prev_byte = key[ kidx ];
   while ( length-- )
   {
      dchr = ( *buffer - key[ kidx ] - prev_byte ) % 256;
      prev_byte = *buffer;
      *buffer++ = dchr;
  
      if ( ++kidx >= klen )
         kidx = 0;
   }
}

