319:/***************************************************************************
320:TILE_Think () - Does Position Calculations for tiles
321: ***************************************************************************/
322:VOID
323:TILE_Think (
324:VOID
325:)
326:{
327:   TILESPOT  *    ts;
328:   TILEDELAY *    td;
329:   INT loopx;
330:   INT loopy;
331:   INT mapspot;
332:   INT x;
333:   INT y;
334:   INT tx;
335:   INT ty;
336:
337:   y        = tileyoff;
338:   mapspot  = tilepos;
339:
340:   ts = tspots;
341:
342:   for ( loopy = 0; loopy < MAP_ONSCREEN; loopy++, y+=32 )
343:   {
344:      x = MAP_LEFT;
345:      for ( loopx = 0; loopx < MAP_COLS; loopx++, x+=32, mapspot++, ts++ )
346:      {
347:         ts->mapspot = mapspot;
348:         ts->x       = x;
349:         ts->y       = y;
350:         ts->item    = titems [ mapspot ];
351:
352:         if ( hits [ mapspot ] < 0 && !tdead [ mapspot ] )
353:         {
354:            SND_3DPatch ( FX_GEXPLO, x + 16, y + 16 );
355:
356:            TILE_DoDamage ( ts->mapspot, 5 );
357:
358:            plr.score += (INT)money [ mapspot ];
359:
360:            TILE_Explode ( ts, 10 );
361:            ANIMS_StartAnim ( A_LARGE_GROUND_EXPLO1, x + 16, y + 16 );
362:
363:            tdead [ mapspot ] = (SHORT)1;
364:         }
365:      }
366:   }
367:
368:   for ( td=first_delay.next; td!=&last_delay; td=td->next )
369:   {
370:      if ( td->mapspot - tilepos > (MAP_ONSCREEN*MAP_COLS) )
371:      {
372:         td = TRemove ( td );
373:         continue;
374:      }
375:
376:      if ( td->frames < 0 )
377:      {
378:         tx = td->ts->x + 8 + random ( 8 );
379:         ty = td->ts->y + 16 + 10;
380:
381:         TILE_DoDamage ( td->mapspot, 20 );
382:
383:         spark_delay++;
384:         flare_delay++;
385:
386:         if ( spark_delay > 2 )
387:         {
388:            ANIMS_StartAnim ( A_GROUND_SPARKLE, tx, ty );
389:            spark_delay = 0;
390:         }
391:
392:         if ( flare_delay > 4 )
393:         {
394:            ANIMS_StartAnim ( A_GROUND_FLARE, tx, ty );
395:            flare_delay = 0;
396:         }
397:
398:         ts = tspots + ( td->mapspot - tilepos );
399:         titems [ ts->mapspot ] = td->item;
400:         eitems [ ts->mapspot ] = td->item;
401:         td = TRemove ( td );
402:         continue;
403:      }
404:
405:      td->frames--;
406:   }
407:}
