423:      pic += sizeof ( GFX_PIC );
424:      TILE_Put ( pic, ts->x, ts->y );
425:  
426:      if ( ts == lastspot ) break;
427:
428:      ts++;
429:   }
430:
431:   tileyoff++;
432:  
433:   if ( tileyoff > 0 )
434:   {
435:      if ( last_tile && tileyoff >=  0 )
436:      {
437:         tileyoff = 0;
438:         scroll_flag = FALSE;
439:      }
440:      else
441:      {
442:         tileyoff -=MAP_BLOCKSIZE;
443:         tilepos -= MAP_COLS;
444:      }
445:
446:      if ( tilepos <= 0 )
447:      {
448:         tilepos = 0;
449:         last_tile = TRUE;
450:      }
451:   }
