         if ( plr.sweapon != EMPTY )
            OBJS_Use ( plr.sweapon );
      }
  
      if ( BUT_2 )
      {
         BUT_2 = FALSE;
         if ( b2_flag == FALSE )
         {
            SND_Patch ( FX_SWEP, 127 );
            b2_flag = TRUE;
            OBJS_GetNext();
         }
      }
      else if ( b2_flag == TRUE )
      {
         b2_flag = FALSE;
      }
  
      if ( BUT_3 )
      {
         BUT_3 = FALSE;
         if ( b3_flag == FALSE )
         {
            b3_flag = TRUE;
            OBJS_Use ( S_MEGA_BOMB );
         }
      }
      else if ( b3_flag == TRUE )
      {
         b3_flag = FALSE;
      }

      if ( startendwave != EMPTY )
      {
         if ( startendwave == 0 )
         {
            end_wave = TRUE;   
         }

         startendwave--;
      }

      gl_cnt++;

      TILE_Think();
      ENEMY_Think();
      ESHOT_Think();
      BONUS_Think();
      SHOTS_Think();
      ANIMS_Think();
      OBJS_Think();
  
