PRIVATE VOID
IPT_GetKeyBoard (
VOID
)
{
   if ( KBD_Key ( k_Left ) || KBD_Key ( k_Right ) )
   {
      if ( KBD_Key ( k_Left ) )
      {
         if ( g_addx >= 0 )
            g_addx = -1;
         g_addx--;
         if ( -g_addx > MAX_ADDX )
            g_addx = -MAX_ADDX;
      }
      else if ( KBD_Key ( k_Right ) )
      {
         if ( g_addx <= 0 )
            g_addx = 1;
         g_addx++;
         if ( g_addx > MAX_ADDX )
            g_addx = MAX_ADDX;
      }
   }
   else
   {
      if ( g_addx != 0 )
         g_addx /= 2;
   }

   if ( KBD_Key ( k_Up ) || KBD_Key ( k_Down ) )
   {
      if ( KBD_Key ( k_Up ) )
      {
         if ( g_addy >= 0 )
            g_addy = -1;
         g_addy--;
         if ( -g_addy > MAX_ADDY )
            g_addy = -MAX_ADDY;
      }
      else if ( KBD_Key ( k_Down ) )
      {
         if ( g_addy <= 0 )
            g_addy = 1;
         g_addy++;
         if ( g_addy > MAX_ADDY )
            g_addy = MAX_ADDY;
      }
   }
   else
   {
      if ( g_addy != 0 )
         g_addy /= 2;
   }
}

/*------------------------------------------------------------------------
IPT_GetMouse (
  ------------------------------------------------------------------------*/
PRIVATE VOID
IPT_GetMouse (
VOID
)
{
   INT plx;
   INT ply;
   INT ptrx;
   INT ptry;

   plx = playerx + ( PLAYERWIDTH/2 );
   ply = playery + ( PLAYERHEIGHT/2 );
   
   ptrx = PTR_X;
   ptry = PTR_Y;

   xm = ptrx - plx;
   ym = ptry - ply;

   if ( xm != 0 )
   {
      xm = xm>>3;
  
      if ( xm == 0 )
         xm = 1;
      else if ( xm > 10 )
         xm = 10;
      else if ( xm < -10 )
         xm = -10;
   }

   if ( ym != 0 )
   {
      ym = ym>>3;
  
      if ( ym == 0 )
         ym = 1;
      else if ( ym > 10 )
         ym = 10;
      else if ( ym < -10 )
         ym = -10;
   }

   g_addx = xm;
   g_addy = ym;

   if ( PTR_B1 )
      buttons [ m_lookup [ 0 ] ] = TRUE;

   if ( PTR_B2 )
      buttons [ m_lookup [ 1 ] ] = TRUE;

   if ( PTR_B3 )
      buttons [ m_lookup [ 2 ] ] = TRUE;
}

PRIVATE VOID
WaitJoyButton (
VOID
)
{
   INT num = 0;

   for (;;)
   {
      num = inp ( 0x201 );
      num = num >> 4;

      if ( ( num & 0x0f ) != 0x0f )
         break;
   }

   for(;;)
   {
      num = inp ( 0x201 );
      num = num >> 4;
      
      if ( ( num & 0x0f ) == 0xf )
         break;
   }

   num = inp ( 0x201 );
   num = inp ( 0x201 );

   for(;;)
   {
      num = inp ( 0x201 );
      num = num >> 4;
      
      if ( ( num & 0x0f ) == 0xf )
         break;
   } 
}

/***************************************************************************
IPT_CalJoy() - Calibrates Joystick ( joystick must be centered )
 ***************************************************************************/
VOID
IPT_CalJoy (
VOID
)
{
   extern BOOL godmode;
   extern INT joy_sx, joy_sy;
   extern INT joy_limit_xh, joy_limit_xl;
   extern INT joy_limit_yh, joy_limit_yl;
   INT   xh, yh;
   INT   xl, yl;

   if ( control != I_JOYSTICK )
      return;

   printf ("\n");

   _disable();
   PTR_ReadJoyStick();
   _enable();

   printf ("CENTER Joystick and press a button\n");
   fflush ( stdout );
   WaitJoyButton();
   PTR_ReadJoyStick();
   _disable();
   PTR_ReadJoyStick();
   _enable();
   joy_sx = joy_x;
   joy_sy = joy_y;

   printf ("PUSH the Joystick in the UPPER LEFT and press a button\n");
   fflush ( stdout );
   WaitJoyButton();
   PTR_ReadJoyStick();
   _disable();
   PTR_ReadJoyStick();
   _enable();
   xl = joy_x;
   yl = joy_y;

   printf ("PUSH the Joystick in the LOWER RIGHT and press a button\n");
   fflush ( stdout );
   WaitJoyButton();
   PTR_ReadJoyStick();
   _disable();
   PTR_ReadJoyStick();
   _enable();
   xh = joy_x;
   yh = joy_y;

   if ( godmode )
   {
      printf ("INPUT xh = %d    xl = %d\n", xh, xl );
      printf ("INPUT yh = %d    yl = %d\n", yh, yl );
   }

   joy_limit_xh = abs ( xh - joy_sx ) / 3;
   joy_limit_xl = -( abs ( xl - joy_sx ) / 3 );
   joy_limit_yh = abs ( yh - joy_sy ) / 3;
   joy_limit_yl = -( abs ( yl - joy_sy ) / 3 );

   if ( godmode )
   {
      printf ("LIMIT xh = %d    xl = %d\n", joy_limit_xh, joy_limit_xl );
      printf ("LIMIT yh = %d    yl = %d\n", joy_limit_yh, joy_limit_yl );
      printf ("CENTER sx = %d    sy = %d\n", joy_sx, joy_sy );
   }

   printf ("\n");
   fflush ( stdout );
}

/***************************************************************************
IPT_Init () - Initializes INPUT system
 ***************************************************************************/
VOID
IPT_Init (
VOID
)
{
   tsm_id = TSM_NewService( IPT_GetButtons, 26, 254, 1 );
   IPT_CalJoy();
}

