 ***************************************************************************/
VOID
IPT_End (
VOID
)
{
   TSM_PauseService( tsm_id );
   PTR_Pause ( FALSE );
   PTR_DrawCursor ( FALSE );
}

/***************************************************************************
IPT_MovePlayer() - Perform player movement for current input device
 ***************************************************************************/
VOID
IPT_MovePlayer (
VOID
)
{
   PRIVATE INT oldx = PLAYERINITX;
   INT delta;
  
   if ( demo_mode == DEMO_PLAYBACK )
      return;

   if ( !control_pause )
   {
      switch ( control )
      {
         default:
