                        {
                           case MULTI_START:
                              sprite->num_frames = curlib->num_frames;
                              sprite->multi = MULTI_END;
                              break;

                           case MULTI_END:
                              sprite->shoot_on = TRUE;
                              break;

                           default:
                              break;
                        }
                        break;
                  }
               }
            }
         }
         else
            sprite->frame_rate--;

