454:            if ( shot->curframe < lib->num_frames)
455:            {
456:               shot->x        = shot->en->x + shot->en->lib->shootx [ shot->gun_num ] - 4;
457:               shot->y        = shot->en->y + shot->en->lib->shooty [ shot->gun_num ];
458:               shot->move.y2  = 200;
459:
