466:               }
467:            }
468:            else
469:               shot->doneflag = TRUE;
470:            break;
471:
472:         default:
473:            if ( shot->curframe >= lib->num_frames )
474:               shot->curframe = 0;
475:
476:            if ( lib->speed )
477:            {
478:               shot->x = shot->move.x;
479:               shot->y = shot->move.y;
480:
481:               MoveSobj ( &shot->move, shot->speed );
482:
483:               if ( shot->speed < lib->speed )
484:                  shot->speed++;
485:            }
486:            else
487:            {
488:               shot->speed--;
489:
490:               if ( shot->speed )
491:               {
492://                  SHADOW_Add ( shot->pic, shot->x, shot->y );
493:
494:                  shot->x = shot->move.x + xpos [ shot->pos ];
495:                  shot->y = shot->move.y + ypos [ shot->pos ];
496:                  shot->move.y++;
497:
498:                  shot->pos++;
499:
500:                  if ( shot->pos >= 16 )
501:                     shot->pos = 0;
502:               }
503:               else
504:               {
505:                  shot->doneflag = TRUE;
506:                  ANIMS_StartAnim ( A_SMALL_AIR_EXPLO, shot->x + 4, shot->y + 4 );
507:               }
508:            }
509:
510:            if ( shot->y >= 200 || shot->y < 0 )
511:               shot->doneflag = TRUE;
512:
513:            if ( shot->x >= 320 || shot->x < 0 )
514:               shot->doneflag = TRUE;
515:
516:            dx = abs ( shot->x - player_cx );
517:            dy = abs ( shot->y - player_cy );
518:
519:            if ( dx < ( PLAYERWIDTH/2 ) && dy < ( PLAYERHEIGHT/2 ) )
520:            {
