VOID
ESHOT_Display (
VOID
)
{
   ESHOT *        shot;
   INT            loop;
   GFX_PIC *      h;
   INT            y;
  
   for ( shot=first_eshot.next; shot!=&last_eshot; shot=shot->next )
   {
      if ( shot->type == ES_LASER )
      {
         for ( loop = shot->y; loop < shot->move.y2; loop+=3 )
         {
            GFX_PutSprite ( shot->pic, shot->x, loop );
