398:/*************************************************************************
399: GLB_Load() Loads a file to a pointer from a .GLB file
400: *************************************************************************/
401:DWORD                         // RETURN : size of item read
402:GLB_Load(
403:BYTE *inmem,               // INPUT: memory pointer or NULL
404:INT  filenum,              // INPUT: file number
405:INT  itemnum               // INPUT: item in file number
406:)
407:{
408:   int      handle;
409:   ITEMINFO *ii;
410:
411:   ASSERT( filenum >= 0 && filenum < num_glbs );
412:
413:	handle = filedesc[ filenum ].handle;
414:	if ( handle == 0 )
415:		return 0;
416:
417:   ASSERT( itemnum < ( WORD ) filedesc[ filenum ].items );
418:
419:   ii = filedesc[ filenum ].item;
420:   ii += itemnum;
421:
422:	if ( inmem != NULL )
423:	{
424:		if ( ii->vm_mem.obj != NULL && inmem != ii->vm_mem.obj )
425:			memcpy( inmem, ii->vm_mem.obj, ii->size );
426:		else
427:		{
428:			lseek( handle, ii->offset, SEEK_SET );
429:      	read( handle, ( VOID * ) inmem, ii->size );
430:#ifdef _SCOTTGAME
431:      	if ( ii->flags & ITF_ENCODED )
432:      	{
433:         	GLB_DeCrypt( serial, inmem, ii->size );
434:      	}
435:#endif
436:		}
437:	}
438:   return ii->size;
439:}
