441:/* - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*
442: GLB_FetchItem() - Loads item into memory only if free core exists.
443: * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/
444:typedef enum { FI_CACHE, FI_DISCARD, FI_LOCK } FI_MODE;
445:
446:PRIVATE VOID *
447:GLB_FetchItem(
448:DWORD handle,
449:FI_MODE	mode
450:)
451:{
452:   BYTE     *obj;
453:   ITEM_H   itm;
454:   ITEMINFO *ii;
455:  
456:   if ( handle == ~0 )
457:	{
458:      EXIT_Error ( "GLB_FetchItem: empty handle." );
459:      return NULL;
460:	}
461:
462:   itm.handle = handle;
463:
464:   ASSERT( itm.id.filenum < ( WORD ) num_glbs );
465:   ASSERT( itm.id.itemnum < ( WORD ) filedesc[ itm.id.filenum ].items );
466:
467:   ii = filedesc[ itm.id.filenum ].item;
468:   ii += itm.id.itemnum;
469:
470:	if ( mode == FI_LOCK )
471:		ii->flags |= ITF_LOCKED;
472:
473:   if ( ( obj = ii->vm_mem.obj ) == NULL )
474:	{
475:		ii->lock_cnt = 0;
476:      if ( ii->size == 0 )
477:         ii->vm_mem.obj = NULL;
478:      else
479:      {
480:         if ( fVmem )
481:			{
482:            obj = VM_Malloc( ii->size,
483:						( ii->flags & ITF_LOCKED ) ? NULL : &ii->vm_mem,
484:						( mode == FI_CACHE ) ? FALSE : TRUE );
485:			}
486:         else
487:			{
488:            obj = calloc( ii->size, sizeof( BYTE ) );
489:			}
490:			if ( mode == FI_LOCK )
491:				ii->lock_cnt = 1;
492:			ii->vm_mem.obj = obj;
493:			if ( obj != NULL )
494:			{
495:	         GLB_Load( obj, itm.id.filenum, itm.id.itemnum );
496:			}
497:      }
498:	}
499:	else if ( mode == FI_LOCK && fVmem )
500:	{
501:		ii->lock_cnt++;
502:		VM_Lock( obj );
503:	}
504:	if ( ii->vm_mem.obj == NULL && mode != FI_CACHE )
505:	{
506:      EXIT_Error ( "GLB_FetchItem: failed on %d bytes, mode=%d.", ii->size, mode );
507:	}
508:	if ( mode == FI_DISCARD && fVmem )
509:		VM_Touch( &ii->vm_mem );
510:
511:	return ii->vm_mem.obj;
512:}
