551:GLB_UnlockItem(
552:DWORD handle
553:)
554:{
555:   ITEM_H   itm;
556:   ITEMINFO *ii;
557:  
558:   if ( handle == ~0 )
559:      return;
560:
561:   itm.handle = handle;
562:
563:   ASSERT( itm.id.filenum < ( WORD ) num_glbs );
564:   ASSERT( itm.id.itemnum < ( WORD ) filedesc[ itm.id.filenum ].items );
565:
566:   ii = filedesc[ itm.id.filenum ].item;
567:   ii += itm.id.itemnum;
568:
569:	if ( ii->vm_mem.obj != NULL && fVmem )
570:	{
