[SOURCE/FX.C#ACDA]
649:/***************************************************************************
650:SND_Patch () - Test patch to see if it will be played by SND_Play
651: ***************************************************************************/
652:VOID
653:SND_Patch (
654:DEFX  type,                // INPUT : DFX type patch to play
655:INT   xpos                 // INPUT : 127=center
656:)
657:{
658:   DFX  * curfld;
659:   BYTE * patch;
660:   INT    loop;
661:   INT    numsnds;
662:   INT    rnd;
663:   INT    volume;
664:
665:   if ( fx_volume < 1 )
666:      return;
667:
668:   rnd      = 0;
669:   numsnds  = 0;
670:
671:   for ( curfld = fxitems, loop = 0; loop < FX_LAST_SND; loop++, curfld++ )
672:   {
673:      if ( curfld->sid == EMPTY ) continue;
674:
675:      if ( !SFX_Playing ( curfld->sid ) && type != loop )
676:         SND_StopPatch ( loop );
677:      else
678:         numsnds++;
679:   }
680:
681:   if ( numsnds > (num_dig+2) )
682:      return;
683:
684:   curfld = &fxitems [ type ];
685:
686:   if ( curfld->odig && !dig_flag )
687:      return;
688:
689:   if ( curfld->item != EMPTY )
690:   {
691:      if ( curfld->rpflag )
692:      {
693:         rnd = random ( 40 );
694:         rnd -= 20;
695:      }
696:
697:      patch = GLB_LockItem ( curfld->item );
698:
699:      volume = (curfld->vol * fx_volume) / 127;
700:
701:      curfld->sid = SFX_PlayPatch ( patch, curfld->pitch + rnd, xpos, volume, 0, curfld->pri );
702:   }
703:
704:   return;
705:}
706:
707:/***************************************************************************
708:SND_3DPatch () - playes a patch in 3d for player during game play
709: ***************************************************************************/
710:VOID
711:SND_3DPatch (
